import {projects,acoustic,assemblySteps,assemblyResult,planOrders,classifySamples,incidents,energyModel} from './models.mjs';
const $=s=>document.querySelector(s); const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('innovation-lab-favorites')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(x=>projects.some(p=>p.id===x));}catch{saved=[];}
const state={sound:{scenario:'normal',rpm:1200,noise:15,playing:false},assembly:{done:[],skipped:[],cursor:0},automation:{duplicate:true,ambiguous:true,failure:false,planned:false,executed:[],resolved:false,failed:false},vision:{light:10,threshold:.8,learned:{},pending:{},version:1},incident:{scenario:'database',analyzed:false,tested:false},energy:{hours:8,idle:4,tariff:.22,standby:true,production:100}};
let audioContext,oscillators=[],toastTimer;
const number=(n,d=1)=>Number(n).toLocaleString('pt-PT',{minimumFractionDigits:d,maximumFractionDigits:d});
const metric=(label,value,unit='')=>`<div class="metric"><small>${label}</small><strong>${value}</strong> <em>${unit}</em></div>`;
const range=(id,label,min,max,value,unit='',step=1)=>`<label for="${id}">${label}</label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><div class="range-label"><span>${min}${unit}</span><output for="${id}" id="${id}-value">${number(value,step<1?2:0)}${unit}</output><span>${max}${unit}</span></div>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
function save(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('innovation-lab-favorites',JSON.stringify(saved));}catch{}render();toast(saved.includes(id)?'Projeto adicionado à seleção.':'Projeto removido da seleção.');}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Relatório exportado.');}
function stopAudio(){for(const o of oscillators){try{o.stop();}catch{}}oscillators=[];if(audioContext){audioContext.close().catch(()=>{});audioContext=null;}state.sound.playing=false;}
async function playAudio(){if(state.sound.playing){stopAudio();render();return;}try{audioContext=new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();const s=state.sound;[1,2,4,9].forEach((harmonic,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=s.scenario==='loose'&&i>1?'sawtooth':'sine';o.frequency.value=s.rpm/60*harmonic;g.gain.value=i===0?.07:s.scenario==='normal'?.008:.025;o.connect(g).connect(audioContext.destination);o.start();oscillators.push(o);});state.sound.playing=true;render();}catch{stopAudio();toast('O navegador não disponibilizou reprodução de áudio.');}}
function graphic(p,small=false){const color=p.color;let shape='';if(p.id==='sound')shape=`<path d="${Array.from({length:110},(_,i)=>`${i?'L':'M'}${i*3},${70+Math.sin(i*.5)*Math.sin(i*.08)*35}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>`;if(p.id==='assembly')shape='<g fill="none" stroke="'+color+'" stroke-width="3"><rect x="120" y="93" width="90" height="13" rx="4"/><path d="M165 15v76"/><ellipse cx="165" cy="52" rx="35" ry="13"/><ellipse cx="165" cy="76" rx="25" ry="9"/></g>';if(p.id==='automation')shape=`<g fill="none" stroke="${color}" stroke-width="2"><rect x="30" y="45" width="65" height="45" rx="7"/><rect x="130" y="45" width="65" height="45" rx="7"/><rect x="230" y="45" width="65" height="45" rx="7"/><path d="M95 67h35m65 0h35"/></g>`;if(p.id==='vision')shape=`<g fill="none" stroke="${color}" stroke-width="2"><path d="M50 45V25h25m200 20V25h-25M50 90v20h25m200-20v20h-25"/><circle cx="165" cy="68" r="35"/><circle cx="165" cy="68" r="14"/></g>`;if(p.id==='incident')shape=`<g fill="none" stroke="${color}" stroke-width="2"><path d="M35 102L80 80l35 12 45-68 43 45 50-30 45 10"/><circle cx="160" cy="24" r="7"/></g>`;if(p.id==='energy')shape=`<g fill="${color}">${[45,78,62,95,48,35,67,83].map((h,i)=>`<rect x="${35+i*34}" y="${115-h}" width="18" height="${h}" rx="3" opacity="${.35+i*.08}"/>`).join('')}</g>`;return `<svg viewBox="0 0 330 140" role="img" aria-label="Ilustração de ${p.name}">${shape}</svg>`;}
function home(){return `<section class="hero"><div><div class="eyebrow">IDEIAS QUE SE PODEM EXPERIMENTAR</div><h1>O próximo projeto<br>começa <span style="color:#7e9671">aqui.</span></h1><p>Seis experiências para explorar o que a tecnologia pode fazer. Altera um cenário, observa o resultado e escolhe o que vale a pena construir.</p><a href="#sound" class="btn">Entrar no laboratório <span>↗</span></a></div><div class="hero-art"><div class="hero-stat"><b>06</b>EXPERIÊNCIAS</div><svg viewBox="0 0 420 280" aria-hidden="true"><defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#ffffff09"/></pattern></defs><rect width="420" height="280" fill="url(#grid)"/><g fill="none" stroke="#b8dc76"><ellipse cx="210" cy="130" rx="95" ry="48" transform="rotate(-25 210 130)"/><ellipse cx="210" cy="130" rx="95" ry="48" transform="rotate(35 210 130)"/><ellipse cx="210" cy="130" rx="95" ry="48" transform="rotate(95 210 130)"/></g><circle cx="210" cy="130" r="20" fill="#d1f36b"/><g fill="#d1f36b"><circle cx="126" cy="104" r="6"/><circle cx="255" cy="204" r="6"/><circle cx="282" cy="81" r="6"/></g></svg><div class="art-label">OBSERVAR → DECIDIR → VALIDAR</div></div></section><div class="section-line"><h2>Escolhe uma experiência</h2><p>6 projetos · 3 áreas · possibilidades abertas</p></div><section class="grid">${projects.map((p,i)=>`<article class="project-card" style="--accent:${p.color}"><div class="card-top"><span class="project-icon">${p.icon}</span><span class="card-number">0${i+1} / 06</span></div><div class="card-label">${p.category}</div><h3>${p.name}</h3><p>${p.desc}</p><div class="card-bottom"><a href="#${p.id}">Experimentar <span>↗</span></a><button class="save ${saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${saved.includes(p.id)?'Remover':'Selecionar'} ${p.name}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'★':'☆'}</button></div></article>`).join('')}</section><div class="favorite-summary"><div><h3>Da demonstração ao projeto.</h3><p>Compara esforço, equipamento e o que precisas de provar.</p></div><a class="btn primary" href="#compare">Comparar os seis projetos ↗</a></div><div class="note">Estas experiências usam dados sintéticos e regras locais. Servem para explorar os conceitos; não representam modelos treinados, medições de equipamentos ou integrações de produção.</div>`;}
function shell(p,body){return `<div class="demo-heading"><div><div class="eyebrow">${p.category} / ${p.name}</div><h1>${p.title}</h1><p>${p.desc}</p></div><button class="btn secondary" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'★ Selecionado':'☆ Selecionar'}</button></div>${body}<div class="note"><b>O que esta demonstração faz:</b> ${p.limit}</div><div class="details"><section class="panel"><h3>Como transformar isto num projeto</h3><ol>${p.steps.map(x=>`<li>${x}</li>`).join('')}</ol><p><b>Stack proposta:</b> ${p.stack}</p></section><section class="panel"><h3>O resultado que importa</h3><p>${p.goal}</p><p><b>Protótipo:</b> ${p.weeks} semanas a 10–15 horas/semana, estimativa.<br><b>Equipamento:</b> ${p.equipment}.</p><button class="btn secondary" data-export="${p.id}">Exportar cenário e plano ↓</button></section></div>`;}
function soundView(){const s=state.sound,r=acoustic(s.scenario,s.rpm,s.noise);const wave=Array.from({length:220},(_,i)=>`${i?'L':'M'}${i*3},${90+Math.sin(i*.44)*(s.scenario==='normal'?14:30)+Math.sin(i*1.6)*(s.scenario==='friction'?20:3)+Math.sin(i*2.31)*s.noise*.18+(s.scenario==='loose'&&i%23<3?40:0)}`).join(' ');return `<div class="demo-layout"><section class="panel"><div class="panel-title"><h3>Monitor acústico</h3><span>SINAL SINTÉTICO · MOTOR M-01</span></div><div class="monitor monitor-grid"><div class="panel-title"><h3>${s.playing?'● A reproduzir':'○ Pronto para escutar'}</h3><span>${s.rpm} RPM</span></div><svg viewBox="0 0 660 180" role="img" aria-label="Forma de onda sintética do cenário selecionado"><path d="M0 90H660" stroke="#ffffff15"/><path d="${wave}" fill="none" stroke="${r.score>40?'#efb27c':'#d1f36b'}" stroke-width="2"/></svg><div class="chart-labels"><span>0,0 s</span><span>0,5 s</span><span>1,0 s</span></div></div><div class="metrics">${metric('ÍNDICE DE DESVIO',r.score,'/100')}${metric('RMS ILUSTRATIVO',r.rms)}${metric('FREQUÊNCIA BASE',r.frequency,'Hz')}</div><div class="result ${r.score>40?'warn':''}" role="status"><h4>${r.status}</h4><p>${r.reason}</p></div></section><section class="panel controls"><div class="panel-title"><h3>Experimenta um cenário</h3><span>01 / 06</span></div><label for="sound-scenario">Estado da máquina</label><select id="sound-scenario"><option value="normal" ${s.scenario==='normal'?'selected':''}>Funcionamento normal</option><option value="friction" ${s.scenario==='friction'?'selected':''}>Atrito adicional</option><option value="loose" ${s.scenario==='loose'?'selected':''}>Componente solto</option></select>${range('rpm','Rotação',600,2400,s.rpm,' RPM',100)}${range('noise','Ruído ambiente',0,80,s.noise,'%')}<button class="btn primary" id="play-sound">${s.playing?'Parar áudio ■':'Ouvir sinal sintetizado ▶'}</button><button class="btn secondary" id="reset-sound">Repor condições</button><p class="footnote">Volume baixo recomendado. O áudio é gerado no navegador e não usa o microfone.</p></section></div>`;}
function assemblyView(){const s=state.assembly,r=assemblyResult(s.done);const next=assemblySteps[s.cursor];return `<div class="demo-layout"><section class="panel"><div class="panel-title"><h3>Bancada de montagem</h3><span>CONJUNTO MECÂNICO · 6 ETAPAS</span></div><div class="monitor monitor-grid">${graphic(projects[1])}<div class="chart-labels"><span>Eixo + anilha + roda</span><span>Vista ilustrativa</span></div></div><div class="progress-track"><div style="width:${r.progress}%"></div></div><div class="step-list">${assemblySteps.map((x,i)=>`<div class="step ${s.done.includes(i)?'done':s.skipped.includes(i)?'skipped':''}"><span class="step-no">${s.done.includes(i)?'✓':i+1}</span><span>${x}</span><small>${s.done.includes(i)?'Confirmado':s.skipped.includes(i)?'Omitido':i===s.cursor?'Próximo':'Pendente'}</small></div>`).join('')}</div></section><section class="panel controls"><div class="panel-title"><h3>Acompanha o processo</h3><span>02 / 06</span></div>${metric('ETAPAS CONFIRMADAS',s.done.length,'/6')}<div class="result ${s.skipped.length?'warn':''}" role="status"><h4>${r.complete?'Montagem completa':s.cursor>=6?'Revisão necessária':next}</h4><p>${r.complete?'Todas as etapas foram confirmadas.':s.skipped.length?'Etapas omitidas: '+s.skipped.map(i=>assemblySteps[i]).join(', '):'Confirma cada etapa ou omite uma para testar a verificação.'}</p></div><button class="btn primary" id="assembly-next" ${s.cursor>=6?'disabled':''}>Confirmar etapa →</button><button class="btn secondary" id="assembly-skip" ${s.cursor>=6?'disabled':''}>Omitir esta etapa</button><button class="btn secondary" id="assembly-fix" ${!s.skipped.length?'disabled':''}>Corrigir primeira omissão</button><button class="btn secondary" id="assembly-reset">Recomeçar montagem</button></section></div>`;}
function automationView(){const s=state.automation,rows=planOrders(s.duplicate,s.ambiguous).map(r=>({...r,status:r.status==='review'&&s.resolved?'ready':r.status}));return `<div class="demo-layout"><section class="panel"><div class="panel-title"><h3>Pedidos → plano de execução</h3><span>FERRAMENTAS SIMULADAS</span></div><div class="table-wrap"><table><thead><tr><th>PEDIDO</th><th>CLIENTE / ARTIGO</th><th>QTD.</th><th>ESTADO</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="mono">${r.id}</td><td>${r.client}<br><small>${r.item}</small></td><td>${r.qty}</td><td><span class="status ${r.status==='ready'?'':r.status==='review'?'warn':'neutral'}">${!s.planned?'Por analisar':s.executed.includes(r.id)&&r.status!=='duplicate'?'Executado':r.status==='ready'?'Pronto':r.status==='review'?'Rever cliente':'Duplicado'}</span></td></tr>`).join('')}</tbody></table></div><div class="metrics">${metric('PRONTOS',s.planned?rows.filter(r=>r.status==='ready').length:'—')}${metric('EXECUTADOS',s.executed.length)}${metric('DUPLICADOS',s.planned?rows.filter(r=>r.status==='duplicate').length:'—')}</div><div class="result ${s.failed?'warn':''}" role="status"><h4>${s.failed?'Falha temporária: progresso guardado':s.executed.length?'Execução local registada':s.planned?'Ensaio concluído':'Prepara primeiro um ensaio'}</h4><p>${s.failed?'O serviço falhou após a primeira operação. Repete a execução para continuar sem duplicar.':s.planned?'Cada pedido válido cria um registo local e prepara uma resposta fictícia. Os duplicados são excluídos.':'Escolhe dificuldades e vê que operações ficariam preparadas.'}</p></div>${s.planned&&rows.some(r=>r.status==='review')?'<button class="btn secondary" id="resolve-client" style="margin-top:15px">Confirmar que “Nova” é Nova Robotics</button>':''}</section><section class="panel controls"><div class="panel-title"><h3>Testar robustez</h3><span>03 / 06</span></div><label class="check"><input id="duplicate" type="checkbox" ${s.duplicate?'checked':''}> Introduzir pedido duplicado</label><label class="check"><input id="ambiguous" type="checkbox" ${s.ambiguous?'checked':''}> Nome de cliente ambíguo</label><label class="check"><input id="failure" type="checkbox" ${s.failure?'checked':''}> Falha temporária na execução</label><button class="btn primary" id="plan-orders">1. Ensaiar alterações</button><button class="btn" id="execute-orders" ${!s.planned?'disabled':''}>2. ${s.failed?'Retomar':'Executar'} operações locais</button><button class="btn secondary" id="reset-orders">Limpar execução</button><p class="footnote">Repetir a execução preserva a unicidade dos pedidos. Não envia emails nem escreve em aplicações externas.</p></section></div>`;}
function objectSvg(type){if(type==='gear')return '<svg viewBox="0 0 140 90" aria-label="Engrenagem ilustrada" role="img"><g transform="translate(70 45)" fill="#8c9b88">'+Array.from({length:10},(_,i)=>`<rect x="-6" y="-34" width="12" height="19" rx="2" transform="rotate(${i*36})"/>`).join('')+'<circle r="25"/><circle r="11" fill="#fff"/></g></svg>';if(type==='bolt')return '<svg viewBox="0 0 140 90" aria-label="Parafuso ilustrado" role="img"><g transform="rotate(-30 70 45)" fill="#9aa9b0"><path d="M45 33h55v24H45z"/><path d="M33 25h20v40H33z"/> <path d="M61 33v24m10-24v24m10-24v24m10-24v24" stroke="#647781" stroke-width="2"/></g></svg>';if(type==='washer')return '<svg viewBox="0 0 140 90" aria-label="Anilha ilustrada" role="img"><circle cx="70" cy="45" r="29" fill="#b9ab8b"/><circle cx="70" cy="45" r="14" fill="#fff"/></svg>';return '<svg viewBox="0 0 140 90" aria-label="Peça desconhecida ilustrada" role="img"><path d="M43 21h29v16h28v28H72v12H43z" fill="#b89878"/><text x="64" y="58" font-size="25" fill="white">?</text></svg>';}
function visionView(){const s=state.vision,rows=classifySamples(s.light,s.threshold,s.learned);return `<div class="demo-layout"><section class="panel"><div class="panel-title"><h3>Lote de inspeção V-24</h3><span>VERSÃO ${s.version}.0 · 4 AMOSTRAS</span></div><div class="vision-grid">${rows.map(r=>`<article class="sample ${r.review?'review':''}"><div class="sample-top"><span>${r.id}</span><span class="status ${r.review?'warn':''}">${r.review?'Revisão':'Automático'}</span></div>${objectSvg(r.type)}<h4>${escape(r.label)}</h4><p>Pontuação ilustrativa: ${number(r.confidence*100,0)}%</p>${r.review?`<div class="review-controls"><select id="label-${r.id}" aria-label="Corrigir classe de ${r.id}"><option>Engrenagem</option><option>Parafuso</option><option>Anilha</option><option>Suporte</option></select><button data-correct="${r.id}" aria-label="Confirmar correção de ${r.id}">✓</button></div>`:''}${s.pending[r.id]?`<p style="margin-top:8px">Correção pendente: ${escape(s.pending[r.id])}</p>`:''}</article>`).join('')}</div><div class="metrics">${metric('AUTOMÁTICOS',rows.filter(r=>!r.review).length)}${metric('PARA REVISÃO',rows.filter(r=>r.review).length)}${metric('CORREÇÕES',Object.keys(s.pending).length)}</div></section><section class="panel controls"><div class="panel-title"><h3>Explorar os limites</h3><span>04 / 06</span></div>${range('light','Alteração de iluminação',0,80,s.light,'%')}${range('threshold','Limiar de decisão',.5,.95,s.threshold,'',.05)}<button class="btn primary" id="publish-vision" ${!Object.keys(s.pending).length?'disabled':''}>Publicar versão demonstrativa</button><button class="btn secondary" id="reset-vision">Repor modelo inicial</button><div class="result"><h4>Revisão antes de aprender</h4><p>Escolhe a classe dos casos em revisão. A publicação incorpora essas correções nas regras da demonstração.</p></div><p class="footnote">Uma versão real precisaria de validação com imagens novas antes de ser publicada.</p></section></div>`;}
function incidentView(){const s=state.incident,i=incidents[s.scenario];return `<div class="demo-layout"><section class="panel"><div class="panel-title"><h3>Cronologia do incidente</h3><span>INC-240 · AMBIENTE DE TESTE</span></div><div class="timeline">${i.events.map(([t,service,message])=>`<div class="event"><time>${t}</time><div><strong>${service}</strong><p>${message}</p></div></div>`).join('')}</div><div class="metrics">${metric('LATÊNCIA P95','2 840','ms')}${metric('TIMEOUTS','18','%')}${metric('EVENTOS',i.events.length)}</div>${s.analyzed?`<div class="result ${s.tested?'':'warn'}" role="status"><h4>${s.tested?i.cause:'Hipótese a verificar'}</h4><p>${s.tested?i.evidence:'Os sintomas isolados não provam a causa. Próxima verificação: '+i.test+'.'}</p></div>${s.tested?`<p class="footnote"><b>Próxima ação:</b> ${i.action}</p>`:''}`:'<p class="footnote">Os três cenários têm timeouts semelhantes. Usa a evidência para os distinguir.</p>'}</section><section class="panel controls"><div class="panel-title"><h3>Investigar com evidência</h3><span>05 / 06</span></div><label for="incident-scenario">Introduzir falha</label><select id="incident-scenario">${Object.entries(incidents).map(([key,value])=>`<option value="${key}" ${s.scenario===key?'selected':''}>${value.name}</option>`).join('')}</select><label>Hipóteses iniciais</label><div class="hypothesis">Pool de ligações <span>${s.tested?(s.scenario==='database'?'Sustentada':'Sem suporte'):'Por testar'}</span></div><div class="hypothesis">Fuga de memória <span>${s.tested?(s.scenario==='memory'?'Sustentada':'Sem suporte'):'Por testar'}</span></div><div class="hypothesis">Dependência externa <span>${s.tested?(s.scenario==='network'?'Sustentada':'Sem suporte'):'Por testar'}</span></div><button class="btn primary" id="analyze-incident">1. Analisar cronologia</button><button class="btn" id="test-incident" ${!s.analyzed?'disabled':''}>2. Executar consulta simulada</button><button class="btn secondary" id="reset-incident">Reiniciar investigação</button></section></div>`;}
function energyView(){const s=state.energy,r=energyModel(s);const chart=Array.from({length:12},(_,h)=>{const active=h<s.hours,base=active?2.8:.8,opt=active?2.8:s.standby?.08:.8;return `<rect x="${h*48+6}" y="${170-base*48}" width="16" height="${base*48}" rx="2" fill="#596d58"/><rect x="${h*48+25}" y="${170-opt*48}" width="16" height="${opt*48}" rx="2" fill="#d1f36b"/>`;}).join('');return `<div class="demo-layout"><section class="panel"><div class="panel-title"><h3>Consumo do processo</h3><span>MESMO TRABALHO · DOIS MODOS</span></div><div class="monitor monitor-grid"><svg viewBox="0 0 590 190" role="img" aria-label="Comparação ilustrativa de potência em operação e espera">${chart}<path d="M0 170H590" stroke="#ffffff20"/></svg><div class="chart-labels"><span>Operação</span><span>Espera / standby</span></div><div class="energy-legend"><span><i class="legend-square base"></i>Modo habitual</span><span><i class="legend-square"></i>Modo proposto</span></div></div><div class="metrics">${metric('CONSUMO HABITUAL',number(r.baseline),'kWh/dia')}${metric('CONSUMO PROPOSTO',number(r.optimized),'kWh/dia')}${metric('REDUÇÃO CALCULADA',number(r.percent),'%')}</div><div class="result" role="status"><h4>${number(r.monthly,2)} € / mês de diferença estimada</h4><p>22 dias úteis. Trabalho preservado a ${s.production}% da carga de referência. Poupança obtida apenas no período de espera.</p></div><details style="margin-top:20px"><summary>Ver fórmula e pressupostos</summary><p>Operação: 2,8 kW × ${number(r.activeHours)} h. Espera habitual: 0,8 kW × ${s.idle} h. Standby: 0,08 kW × ${s.idle} h. Diferença mensal = diferença diária × tarifa × 22. Exclui transições, perdas e custos de implementação. O gráfico é ilustrativo; os totais usam as horas escolhidas.</p></details></section><section class="panel controls"><div class="panel-title"><h3>Alterar pressupostos</h3><span>06 / 06</span></div>${range('hours','Janela de operação',2,12,s.hours,' h')}${range('idle','Tempo de espera',0,8,s.idle,' h')}${range('production','Carga de trabalho',50,100,s.production,'%')}${range('tariff','Tarifa de energia',.1,.5,s.tariff,' €/kWh',.01)}<label class="check"><input id="standby" type="checkbox" ${s.standby?'checked':''}> Ativar standby durante a espera</label><button class="btn secondary" id="reset-energy">Repor pressupostos</button></section></div>`;}
function compare(){const selected=projects.filter(p=>saved.includes(p.id));return `<div class="eyebrow">ESCOLHER O QUE CONSTRUIR</div><h1>Compara. Decide.<br>Começa pequeno.</h1><p class="compare-intro">O melhor projeto combina o teu interesse, os recursos disponíveis e um resultado que consigas demonstrar. Seleciona os favoritos e exporta o plano.</p><section class="panel" style="margin-top:28px"><div class="panel-title"><h3>Os seis caminhos</h3><span>PRAZOS DE PROTÓTIPO · ESTIMATIVAS</span></div><div class="table-wrap"><table class="compare-table"><thead><tr><th>PROJETO</th><th>PRAZO</th><th>EQUIPAMENTO</th><th>DIFICULDADE</th><th>SELEÇÃO</th></tr></thead><tbody>${projects.map(p=>`<tr><td><a href="#${p.id}">${p.icon} ${p.name} ↗</a></td><td>${p.weeks} semanas</td><td>${p.equipment}</td><td>${'●'.repeat(p.difficulty)}${'○'.repeat(5-p.difficulty)}</td><td><button class="save ${saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="Selecionar ${p.name}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'★':'☆'}</button></td></tr>`).join('')}</tbody></table></div><p class="footnote">Estimativas para uma pessoa a 10–15 horas/semana. Dificuldade relativa de 1 a 5, não uma avaliação de mercado.</p></section><div class="section-line"><h2>A tua seleção</h2><button class="btn secondary" id="export-selection" ${!selected.length?'disabled':''}>Exportar planos ↓</button></div>${selected.length?`<div class="grid">${selected.map(p=>`<section class="panel"><h3>${p.name}</h3><p style="font-size:12px;color:var(--muted)">${p.goal}</p><ol style="font-size:11px;line-height:1.9;padding-left:17px">${p.steps.map(x=>`<li>${x}</li>`).join('')}</ol><a href="#${p.id}" class="btn secondary">Voltar à demonstração ↗</a></section>`).join('')}</div>`:'<div class="panel empty">Seleciona ★ nos projetos que mais te interessam.</div>'}<div class="note">Para uma demonstração física acessível: EchoSense. Para software e diagnóstico: TraceRoom. Para impacto visual numa bancada: Assembly Guide.</div>`;}
function render(){const id=location.hash.slice(1)||'home';const p=projects.find(x=>x.id===id);$('#saved-count').textContent=saved.length;$('#navigation').innerHTML=`<a class="nav-item ${id==='home'?'active':''}" href="#home"><span class="nav-symbol">⊞</span>Visão geral</a>${projects.map(x=>`<a class="nav-item ${id===x.id?'active':''}" href="#${x.id}"><span class="nav-symbol">${x.icon}</span>${x.name}</a>`).join('')}`;$('#breadcrumb').textContent='Laboratório / '+(p?p.name:id==='compare'?'Comparar projetos':'Visão geral');document.title=(p?p.name+' — ':id==='compare'?'Comparar — ':'')+'Innovation Lab';document.documentElement.style.setProperty('--accent',p?.color||'#719478');const views={sound:soundView,assembly:assemblyView,automation:automationView,vision:visionView,incident:incidentView,energy:energyView};$('#content').innerHTML=p?shell(p,views[id]()):id==='compare'?compare():home();bind();}
function on(id,event,fn){const el=$('#'+id);if(el)el.addEventListener(event,fn);}
function bind(){document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>save(b.dataset.save));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{const p=projects.find(p=>p.id===b.dataset.export);download(p.id+'-cenario.json',{project:p,simulation:true,state:state[p.id]});});on('export-selection','click',()=>download('innovation-lab-planos.json',{simulation:true,projects:projects.filter(p=>saved.includes(p.id))}));
on('sound-scenario','change',e=>{stopAudio();state.sound.scenario=e.target.value;render();});for(const [id,key]of [['rpm','rpm'],['noise','noise']])on(id,'change',e=>{stopAudio();state.sound[key]=+e.target.value;render();});on('play-sound','click',playAudio);on('reset-sound','click',()=>{stopAudio();Object.assign(state.sound,{scenario:'normal',rpm:1200,noise:15});render();});
on('assembly-next','click',()=>{const s=state.assembly;if(s.cursor<6)s.done.push(s.cursor++);render();});on('assembly-skip','click',()=>{const s=state.assembly;if(s.cursor<6)s.skipped.push(s.cursor++);render();});on('assembly-fix','click',()=>{const s=state.assembly;if(s.skipped.length)s.done.push(s.skipped.shift());render();});on('assembly-reset','click',()=>{Object.assign(state.assembly,{done:[],skipped:[],cursor:0});render();});
for(const id of ['duplicate','ambiguous','failure'])on(id,'change',e=>{state.automation[id]=e.target.checked;Object.assign(state.automation,{planned:false,executed:[],resolved:false,failed:false});render();});on('plan-orders','click',()=>{state.automation.planned=true;render();});on('resolve-client','click',()=>{state.automation.resolved=true;render();});on('execute-orders','click',()=>{const s=state.automation;if(!s.planned)return;const ready=planOrders(s.duplicate,s.ambiguous).filter(r=>r.status==='ready'||r.status==='review'&&s.resolved).filter(r=>!s.executed.includes(r.id));if(s.failure&&!s.failed&&ready.length){s.executed.push(ready[0].id);s.failed=true;}else{ready.forEach(r=>s.executed.push(r.id));s.failed=false;s.failure=false;}render();if(!ready.length)toast('A execução já está atualizada. Nenhuma operação duplicada.');});on('reset-orders','click',()=>{Object.assign(state.automation,{planned:false,executed:[],resolved:false,failed:false});render();});
for(const id of ['light','threshold'])on(id,'change',e=>{state.vision[id]=+e.target.value;render();});document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>{state.vision.pending[b.dataset.correct]=$('#label-'+b.dataset.correct).value;render();});on('publish-vision','click',()=>{const s=state.vision;Object.assign(s.learned,s.pending);s.pending={};s.version++;render();toast('Nova versão demonstrativa publicada localmente.');});on('reset-vision','click',()=>{Object.assign(state.vision,{light:10,threshold:.8,learned:{},pending:{},version:1});render();});
on('incident-scenario','change',e=>{Object.assign(state.incident,{scenario:e.target.value,analyzed:false,tested:false});render();});on('analyze-incident','click',()=>{state.incident.analyzed=true;render();});on('test-incident','click',()=>{if(state.incident.analyzed)state.incident.tested=true;render();});on('reset-incident','click',()=>{Object.assign(state.incident,{analyzed:false,tested:false});render();});
for(const id of ['hours','idle','production','tariff'])on(id,'change',e=>{state.energy[id]=+e.target.value;render();});on('standby','change',e=>{state.energy.standby=e.target.checked;render();});on('reset-energy','click',()=>{Object.assign(state.energy,{hours:8,idle:4,tariff:.22,standby:true,production:100});render();});
document.querySelectorAll('input[type=range]').forEach(input=>input.addEventListener('input',()=>{const output=$('#'+input.id+'-value');const unit=output.textContent.replace(/^[\d\s,.]+/,'');output.textContent=number(input.value,+input.step<1?2:0)+unit;}));}
$('#compare-button').onclick=()=>{location.hash='compare';};window.addEventListener('hashchange',()=>{stopAudio();render();window.scrollTo(0,0);$('#content').focus({preventScroll:true});});window.addEventListener('pagehide',stopAudio);render();
